// Deterministic mock transaction dataset (no randomness)
const transactions = [
  // #1 TXN-001 — Completely valid transaction (should pass immediately)
  { transaction_id: 'TXN-001', customer_id: 'CUST-1001', amount: 250.00, currency: 'USD', transaction_date: '2026-09-01', transaction_type: 'purchase', status: 'completed' },
  // #2 TXN-002 — Missing required field (customer_id) -> uncorrectable
  { transaction_id: 'TXN-002', amount: 99.99, currency: 'EUR', transaction_date: '2026-09-02', transaction_type: 'refund', status: 'pending' },
  // #3 TXN-003 — Invalid currency ("usd") -> correctable to "USD"
  { transaction_id: 'TXN-003', customer_id: 'CUST-1003', amount: 40.50, currency: 'usd', transaction_date: '2026-09-03', transaction_type: 'purchase', status: 'completed' },
  // #4 TXN-004 — Invalid amount (negative) -> uncorrectable
  { transaction_id: 'TXN-004', customer_id: 'CUST-1004', amount: -75.00, currency: 'GBP', transaction_date: '2026-09-04', transaction_type: 'withdrawal', status: 'completed' },
  // #5 TXN-005 — Invalid status ("done") -> correctable to "completed"
  { transaction_id: 'TXN-005', customer_id: 'CUST-1005', amount: 500.00, currency: 'INR', transaction_date: '2026-09-05', transaction_type: 'transfer', status: 'done' },
  // #6 TXN-006 — Invalid date format ("09/06/2026") -> correctable to "2026-09-06"
  { transaction_id: 'TXN-006', customer_id: 'CUST-1006', amount: 12.00, currency: 'JPY', transaction_date: '09/06/2026', transaction_type: 'deposit', status: 'pending' },
  // #7 TXN-007 — Multiple errors: lowercase currency + status casing (both correctable)
  { transaction_id: 'TXN-007', customer_id: 'CUST-1007', amount: 320.00, currency: 'eur', transaction_date: '2026-09-07', transaction_type: 'purchase', status: 'Completed' },
  // #8 TXN-008 — Uncorrectable: invalid transaction_type + missing amount
  { transaction_id: 'TXN-008', customer_id: 'CUST-1008', currency: 'USD', transaction_date: '2026-09-08', transaction_type: 'quantum_teleport', status: 'completed' },
];

return transactions.map((t) => ({ json: t }));

// Deterministic validation. No network, no LLM.
let tx;
try {
  tx = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  return JSON.stringify({ valid: false, errors: ['Input is not valid JSON: ' + e.message], validated_transaction: {} });
}
if (tx === null || typeof tx !== 'object' || Array.isArray(tx)) {
  return JSON.stringify({ valid: false, errors: ['Input must be a transaction object'], validated_transaction: {} });
}

const errors = [];
const validCurrencies = ['USD', 'EUR', 'GBP', 'INR', 'JPY'];
const validTypes = ['purchase', 'refund', 'transfer', 'withdrawal', 'deposit'];
const validStatuses = ['pending', 'completed', 'failed', 'cancelled'];
const requiredFields = ['transaction_id', 'customer_id', 'amount', 'currency', 'transaction_date', 'transaction_type', 'status'];

for (const f of requiredFields) {
  if (tx[f] === undefined || tx[f] === null || tx[f] === '') {
    errors.push('Missing required field: ' + f);
  }
}

if (tx.amount !== undefined && tx.amount !== null && tx.amount !== '') {
  const amt = Number(tx.amount);
  if (Number.isNaN(amt)) {
    errors.push('Invalid amount: "' + tx.amount + '" is not a number');
  } else if (amt <= 0) {
    errors.push('Invalid amount: must be greater than zero (got ' + amt + ')');
  }
}

if (tx.currency !== undefined && tx.currency !== null && tx.currency !== '' && !validCurrencies.includes(tx.currency)) {
  errors.push('Invalid currency: "' + tx.currency + '". Allowed: ' + validCurrencies.join(', '));
}

if (tx.transaction_type !== undefined && tx.transaction_type !== null && tx.transaction_type !== '' && !validTypes.includes(tx.transaction_type)) {
  errors.push('Invalid transaction_type: "' + tx.transaction_type + '". Allowed: ' + validTypes.join(', '));
}

if (tx.status !== undefined && tx.status !== null && tx.status !== '' && !validStatuses.includes(tx.status)) {
  errors.push('Invalid transaction status: "' + tx.status + '". Allowed: ' + validStatuses.join(', '));
}

if (tx.transaction_date !== undefined && tx.transaction_date !== null && tx.transaction_date !== '') {
  const dateRe = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRe.test(String(tx.transaction_date))) {
    errors.push('Invalid date format: "' + tx.transaction_date + '". Expected YYYY-MM-DD');
  } else {
    const d = new Date(String(tx.transaction_date) + 'T00:00:00Z');
    if (Number.isNaN(d.getTime())) {
      errors.push('Invalid date value: "' + tx.transaction_date + '"');
    }
  }
}

return JSON.stringify({
  valid: errors.length === 0,
  errors: errors,
  validated_transaction: errors.length === 0 ? tx : {},
});

